    // 获取全套奖励文本列表
    getFullSetBonusLines(groupKey, DATA_TABLES) {
      const g = this.getSetGroup(groupKey);
      if (!g) return [];
      const PROPS = (DATA_TABLES && DATA_TABLES.props) || {};
      const SKILLS = (DATA_TABLES && DATA_TABLES.skills) || {};
      const numStrings = this.numStrings || {};
      const lines = [];

      const formatPropEntry = (propStr, paramStr, minStr, maxStr) => {
        const propList = String(propStr).split(',').map(s => s.trim()).filter(Boolean);
        const min = parseInt(minStr, 10) || 0;
        const max = parseInt(maxStr, 10) || min;
        const param = parseInt(paramStr, 10) || 0;

        for (const pIdStr of propList) {
          const pId = parseInt(pIdStr, 10);
          const def = PROPS[String(pId)] || {};
          const val = min;

          if (pId === 375) { // desc_top
            const s = numStrings[String(param)] || numStrings[String(val)] || ('string #' + param);
            lines.push(s + ' [string #' + param + ']');
            continue;
          }
          if (pId === 98) { // 赋予状态
            lines.push('赋予状态: #' + param + ' 游戏状态 #' + param + '/State #' + param);
            continue;
          }
          if (pId === 383) { // 协同加成
            const sk = SKILLS[String(param)];
            let skName = typeof sk === 'string' ? sk : (sk && sk.name ? sk.name : '');
            if (!skName) {
              skName = param === 1605 ? '奥术狂怒/Arcane Fury' : ('技能#' + param);
            }
            lines.push('+' + val + '% 协同加成: ' + skName);
            continue;
          }
          if (pId === 83) { // 职业技能
            const cNames = ['亚马逊', '法师', '死灵法师', '圣骑士', '野蛮人', '德鲁伊', '刺客'];
            const cName = cNames[param] || '职业';
            lines.push('+' + val + ' ' + cName + '技能等级');
            continue;
          }
          if (pId === 74) { // 每秒生命恢复 (hpregen: 1000 => 100)
            const v = Math.round(val / 10);
            lines.push('+' + v + ' 每秒生命恢复');
            continue;
          }
          if (pId === 171) { // 防御加成 (BtD)
            lines.push('+' + val + '% 防御加成 (BtD)');
            continue;
          }
          if (pId === 96) { // 移动速度 (FRW)
            lines.push('+' + val + '% 移动速度 (FRW)');
            continue;
          }
          if (pId === 361) { // 精力 (ENG)
            lines.push('+' + val + '% 精力 (ENG)');
            continue;
          }
          if (pId === 77) { // 最大法力
            lines.push('最大法力 +' + val + '%');
            continue;
          }
          if (pId === 36) { // 物理抗性
            lines.push('物理抗性 +' + val + '%');
            continue;
          }
          if (pId === 338 || pId === 339 || pId === 340) { // 躲避伤害
            lines.push('+' + val + '% 躲避伤害');
            continue;
          }

          const sign = val >= 0 ? '+' : '';
          const pos = def.pos || def.stat || ('属性#' + pId);
          if (def.df === 2) {
            lines.push(sign + val + '% ' + pos);
          } else {
            lines.push(sign + val + ' ' + pos);
          }
        }
      };

      // 1. 全套专属属性 (fullProps)
      for (const bp of g.fullProps) {
        formatPropEntry(bp.prop, bp.param, bp.min, bp.max);
      }
      // 2. 件数阶段属性 (partProps) 在全套时一并享受
      for (const bp of g.partProps) {
        formatPropEntry(bp.prop, bp.param, bp.min, bp.max);
      }
      return lines;
    }
